package at.andrew.squashtap;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.*;import java.util.*;
public class MatchCsvTest {
 static MatchBook finished(String id){MatchBook b=new MatchBook(new MatchState(id,3),Clock.fixed(Instant.parse("2026-11-04T09:00:00Z"),ZoneId.of("Europe/Vienna")));for(int s=0;s<2;s++){for(int i=0;i<11;i++)b.add(0);if(s==0)b.nextGame();}return b;}
 @Test public void exportImportRoundtripKeepsUnicodeQuotesTimesAndSetScores(){MatchBook b=finished("saved");OpponentDirectory d=new OpponentDirectory();String id=d.add("Änne, \"李\"");d.assign("saved",id);List<MatchCsv.Row> rows=MatchCsv.parse(MatchCsv.export(b.newestFirst(),d));assertEquals(1,rows.size());assertEquals("Änne, \"李\"",rows.get(0).name);assertEquals(b.result("saved").startedAt,rows.get(0).result.startedAt);assertEquals(11,rows.get(0).result.points(1,0));}
 @Test public void spreadsheetFormulaEscapingIsReversibleIncludingLiteralApostrophes(){for(String name:new String[]{"=SUM(1,2)","+Martin","-Alice","@Bob","'=SUM(1,2)","'Andrew"}){OpponentDirectory d=new OpponentDirectory();d.assign("saved",d.add(name));String csv=MatchCsv.export(finished("saved").newestFirst(),d);assertEquals(name,MatchCsv.parse(csv).get(0).name);assertTrue(csv.contains("\"'"));}}
 @Test public void semicolonAndBomFilesAreAccepted(){String csv=MatchCsv.export(finished("saved").newestFirst(),new OpponentDirectory());assertEquals(1,MatchCsv.parse(csv.replace(',',';')).size());}
 @Test public void mergeKeepsActiveRalliesUndoTimingAndDirectory(){MatchBook original=new MatchBook(new MatchState("active",5));original.add(0);original.add(1);String before=original.encode();MatchCsv.Plan p=MatchCsv.plan(original,new OpponentDirectory(),MatchCsv.parse(MatchCsv.export(finished("foreign").newestFirst(),new OpponentDirectory())));assertEquals(before,original.encode());assertEquals(1,p.added);assertEquals(1,p.book.current().game().blue());assertEquals(1,p.book.current().game().red());assertTrue(p.book.undo());assertEquals(0,p.book.current().game().red());}
 @Test public void reimportSkipsDuplicateEvenWhenLocalReferenceWasRenumbered(){MatchBook book=finished("local");book.newMatch("active",3);String csv=MatchCsv.export(finished("foreign").newestFirst(),new OpponentDirectory());MatchCsv.Plan a=MatchCsv.plan(book,new OpponentDirectory(),MatchCsv.parse(csv));assertEquals(1,a.renumbered);assertEquals(2,a.book.result("foreign").number);MatchCsv.Plan b=MatchCsv.plan(a.book,a.directory,MatchCsv.parse(csv));assertEquals(0,b.added);assertEquals(1,b.duplicates);assertEquals(0,b.conflicts);}
 @Test public void deletedReferencesAreNotReused(){MatchBook book=finished("local");book.delete("local");book.newMatch("active",3);MatchCsv.Plan p=MatchCsv.plan(book,new OpponentDirectory(),MatchCsv.parse(MatchCsv.export(finished("foreign").newestFirst(),new OpponentDirectory())));assertEquals(2,p.book.result("foreign").number);assertEquals(p.book.encode(),MatchBook.decode(p.book.encode()).encode());}
 @Test public void currentDeletedResultCannotBeResurrectedThroughCsv(){MatchBook book=finished("saved");String csv=MatchCsv.export(book.newestFirst(),new OpponentDirectory());book.delete("saved");MatchCsv.Plan p=MatchCsv.plan(book,new OpponentDirectory(),MatchCsv.parse(csv));assertEquals(0,p.added);assertEquals(1,p.conflicts);assertTrue(p.book.currentDeleted());assertNull(p.book.result("saved"));}
 @Test public void conflictingSameIdIsSkippedWithoutOverwriting(){MatchBook book=finished("saved");MatchResult old=book.result("saved");MatchResult changed=new MatchResult("saved",old.date,old.number,3,new int[][]{{0,11},{0,11}},old.startedAt,old.finishedAt,old.zoneId);MatchCsv.Plan p=MatchCsv.plan(book,new OpponentDirectory(),MatchCsv.parse(MatchCsv.export(Collections.singletonList(changed),new OpponentDirectory())));assertEquals(1,p.conflicts);assertEquals(0,p.book.result("saved").winner());}
 @Test public void importCreatesOpponentButDoesNotRenameExistingPeople(){OpponentDirectory d=new OpponentDirectory();String id=d.add("Martin");d.assign("saved",id);String csv=MatchCsv.export(finished("saved").newestFirst(),d);d.rename(id,"Marty");MatchCsv.Plan p=MatchCsv.plan(new MatchBook(new MatchState("active",3)),d,MatchCsv.parse(csv));assertEquals("Marty",p.directory.nameFor("saved"));}
 @Test public void invalidCsvIsRejectedBeforeAnyMutation(){String csv=MatchCsv.export(finished("saved").newestFirst(),new OpponentDirectory());assertThrows(IllegalArgumentException.class,()->MatchCsv.parse(csv.replace("\"11\"","\"12\"")));assertThrows(IllegalArgumentException.class,()->MatchCsv.parse(csv.replace("\"0\",\"2\",\"0\"","\"9\",\"2\",\"0\"")));assertThrows(IllegalArgumentException.class,()->MatchCsv.parse("bad,header\n"));assertThrows(IllegalArgumentException.class,()->MatchCsv.parse(MatchCsv.HEADER+"\n\"unclosed"));}
 @Test public void legacyMissingTimesStayMissing(){MatchResult r=new MatchResult("legacy","2026-11-03",1,3,new int[][]{{11,4},{11,2}});MatchCsv.Row row=MatchCsv.parse(MatchCsv.export(Collections.singletonList(r),new OpponentDirectory())).get(0);assertEquals(0,row.result.startedAt);assertEquals(-1,row.result.durationMillis());}
 @Test public void emptyExportIsAValidTemplate(){assertTrue(MatchCsv.parse(MatchCsv.export(Collections.emptyList(),new OpponentDirectory())).isEmpty());}
 @Test public void foreignReferenceCannotExhaustTheLocalDailyCounter(){MatchResult foreign=new MatchResult("foreign","2026-11-04",Integer.MAX_VALUE,3,new int[][]{{11,4},{11,5}});MatchBook book=new MatchBook(new MatchState("active",3));MatchCsv.Plan p=MatchCsv.plan(book,new OpponentDirectory(),MatchCsv.parse(MatchCsv.export(Collections.singletonList(foreign),new OpponentDirectory())));assertEquals(1,p.book.result("foreign").number);assertEquals(1,p.renumbered);assertEquals(p.book.encode(),MatchBook.decode(p.book.encode()).encode());}
}
